//! The mask ROM's symbols: the function and data symbols of each chip's ROM
//! (and the ESP8266's peripheral register blocks), from the ROM linker
//! scripts of ESP-IDF and the ESP8266 RTOS and NONOS SDKs. ESP32-family
//! peripherals come from Espressif's SVD files instead.
//!
//! The tables are `data/rom_symbols/<chip>.txt`, generated by
//! `scripts/gen_rom_symbols.py` (which records where each chip's come from)
//! and embedded in the plugin. Each line of such a file is one of:
//!
//! * `# ...`: a comment;
//! * `code <start> <end>`: an address range of the mask ROM's code, on the
//!   chips whose ROM code and data share an address range (the executable
//!   sections of Espressif's ROM ELF files): the ROM symbols in them are
//!   functions, the others data;
//! * `revision <n>`: the symbols that follow only exist in the ROM of chip
//!   revision `n` (major * 100 + minor, as in the image header) and later;
//! * `<address> <name>`: a symbol.
//!
//! Addresses are hexadecimal, without a prefix.

use std::sync::OnceLock;

use crate::espressif::{Chip, Symbols};

/// A chip's ROM symbol tables.
#[derive(Debug)]
pub struct RomSymbols {
    /// The symbols of every revision of the chip.
    pub base: Symbols,
    /// The symbols only in the ROM of a minimum chip revision (major * 100 +
    /// minor) and later, by revision.
    pub revisions: &'static [(u16, Symbols)],
    /// The address ranges of the mask ROM's code, if the file gives them.
    pub code: Option<&'static [(u32, u32)]>,
}

/// The embedded tables, in the order of [`Chip::ALL`].
static FILES: [(Chip, &str); 9] = [
    (
        Chip::Esp8266,
        include_str!("../../data/rom_symbols/esp8266.txt"),
    ),
    (
        Chip::Esp32,
        include_str!("../../data/rom_symbols/esp32.txt"),
    ),
    (
        Chip::Esp32S2,
        include_str!("../../data/rom_symbols/esp32s2.txt"),
    ),
    (
        Chip::Esp32S3,
        include_str!("../../data/rom_symbols/esp32s3.txt"),
    ),
    (
        Chip::Esp32C2,
        include_str!("../../data/rom_symbols/esp32c2.txt"),
    ),
    (
        Chip::Esp32C3,
        include_str!("../../data/rom_symbols/esp32c3.txt"),
    ),
    (
        Chip::Esp32C6,
        include_str!("../../data/rom_symbols/esp32c6.txt"),
    ),
    (
        Chip::Esp32H2,
        include_str!("../../data/rom_symbols/esp32h2.txt"),
    ),
    (
        Chip::Esp32C5,
        include_str!("../../data/rom_symbols/esp32c5.txt"),
    ),
];

/// The chip's ROM symbol tables, read from its embedded file on first use.
pub fn of(chip: Chip) -> &'static RomSymbols {
    static TABLES: [OnceLock<RomSymbols>; 9] = [const { OnceLock::new() }; 9];
    let index = FILES
        .iter()
        .position(|&(c, _)| c == chip)
        .expect("every chip has a ROM symbol file");
    TABLES[index].get_or_init(|| {
        parse(FILES[index].1)
            .unwrap_or_else(|err| panic!("data/rom_symbols/{}.txt: {err}", chip.platform_name()))
    })
}

/// Parses a ROM symbol file (see the module documentation). The tables are
/// kept for the life of the process, so they are leaked.
fn parse(text: &'static str) -> Result<RomSymbols, String> {
    let mut base = Vec::new();
    let mut revisions: Vec<(u16, Vec<(&'static str, u32)>)> = Vec::new();
    let mut code = Vec::new();
    for (n, line) in text.lines().enumerate() {
        let error = |what: &str| format!("line {}: {what}: {line:?}", n + 1);
        let hex = |s: &str| u32::from_str_radix(s, 16).map_err(|_| error("bad address"));
        let words: Vec<&'static str> = line.split_ascii_whitespace().collect();
        match words.as_slice() {
            [] => {}
            [comment, ..] if comment.starts_with('#') => {}
            ["code", start, end] => {
                let (start, end) = (hex(start)?, hex(end)?);
                if start >= end {
                    return Err(error("empty code range"));
                }
                code.push((start, end));
            }
            ["revision", rev] => {
                let rev = rev.parse().map_err(|_| error("bad revision"))?;
                if revisions.last().is_some_and(|&(last, _)| last >= rev) {
                    return Err(error("revisions out of order"));
                }
                revisions.push((rev, Vec::new()));
            }
            [addr, name] => {
                let table = match revisions.last_mut() {
                    Some((_, table)) => table,
                    None => &mut base,
                };
                table.push((*name, hex(addr)?));
            }
            _ => return Err(error("unexpected line")),
        }
    }
    let revisions: Vec<(u16, Symbols)> = revisions
        .into_iter()
        .map(|(rev, table)| (rev, &*table.leak()))
        .collect();
    Ok(RomSymbols {
        base: base.leak(),
        revisions: revisions.leak(),
        code: (!code.is_empty()).then(|| &*code.leak()),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_chip_has_its_file() {
        for (i, chip) in Chip::ALL.into_iter().enumerate() {
            assert_eq!(FILES[i].0, chip);
            let tables = of(chip);
            assert!(!tables.base.is_empty(), "{chip:?}");
            assert!(
                tables.revisions.iter().all(|(_, t)| !t.is_empty()),
                "{chip:?}"
            );
        }
    }

    #[test]
    fn parses_every_kind_of_line() {
        let tables = parse(
            "# comment\ncode 40000000 40001000\n40000010 memcpy\n\
             3fc00000 table\nrevision 3\n40000020 newer\nrevision 101\n40000030 newest\n",
        )
        .unwrap();
        assert_eq!(
            tables.base,
            [("memcpy", 0x4000_0010), ("table", 0x3fc0_0000)]
        );
        assert_eq!(
            tables.revisions,
            [
                (3, &[("newer", 0x4000_0020)][..]),
                (101, &[("newest", 0x4000_0030)][..])
            ]
        );
        assert_eq!(tables.code, Some(&[(0x4000_0000, 0x4000_1000)][..]));
        assert_eq!(parse("40000010 memcpy\n").unwrap().code, None);
    }

    #[test]
    fn rejects_malformed_lines() {
        for text in [
            "4000001x memcpy\n",
            "40000010\n",
            "40000010 memcpy extra\n",
            "code 40001000 40000000\n",
            "revision x\n",
            "revision 101\nrevision 3\n",
        ] {
            assert!(parse(text).is_err(), "{text:?}");
        }
    }
}
